import path from 'node:path';
import { Bot, InlineKeyboard, InputFile, Keyboard } from 'grammy';
// import { Bot, InlineKeyboard, Keyboard } from 'grammy';
import { config } from '../config.js';
// import { User } from '../models/index.js';
import { LANGS, languageScreen, tr } from '../i18n.js';

export let bot = null;

const normalizePhone = (p) => (p.startsWith('+') ? p : `+${p}`);

// Screen 2: language selection
async function sendLanguageScreen(ctx) {
  const kb = new InlineKeyboard();
  for (const [code, { label, flag }] of Object.entries(LANGS)) {
    kb.text(`1️⃣ ${flag} ${label}`, `lang:${code}`).row();
  }
  await ctx.reply(languageScreen, { parse_mode: 'HTML', reply_markup: kb });
}

// Screen 3: ask for phone
async function sendPhonePrompt(ctx, lang) {
  const kb = new Keyboard().requestContact(tr(lang).sharePhoneBtn).resized().oneTime();
  await ctx.reply(tr(lang).sharePhone, { reply_markup: kb });
}

// Screen 4: confirmation + app buttons
async function sendAppScreen(ctx, lang, { withConfirm }) {
  const tx = tr(lang);
  if (withConfirm) {
    await ctx.reply(tx.confirmed, { reply_markup: { remove_keyboard: true } });
  }
  const link = `https://t.me/${config.botUsername}?start=ref_${ctx.from.id}`;
  const shareUrl =
    `https://t.me/share/url?url=${encodeURIComponent(link)}` +
    `&text=${encodeURIComponent(tx.inviteText)}`;

  const kb = new InlineKeyboard();
  if (config.webAppUrl.startsWith('https://')) kb.webApp(tx.appBtn, config.webAppUrl).row();
  kb.url(tx.inviteBtn, shareUrl);
  await ctx.reply(tx.tapToOpen, { reply_markup: kb });
}

export function createBot() {
  if (!config.botToken) return null;
  bot = new Bot(config.botToken);

  bot.command('start', async (ctx) => {
    const id = ctx.from.id;
    let user = await User.findOne({ telegramId: id });

    if (!user) {
      let referredBy;
      const m = /^ref_(\d+)$/.exec(ctx.match ?? '');
      if (m && Number(m[1]) !== id) {
        const referrer = await User.findOne({ telegramId: Number(m[1]) });
        if (referrer) referredBy = referrer.telegramId;
      }
      user = await User.create({
        telegramId: id,
        firstName: ctx.from.first_name,
        username: ctx.from.username,
        referredBy,
        role: config.adminIds.includes(id) ? 'ADMIN' : 'USER',
      });
    }

    if (!user.language) return sendLanguageScreen(ctx);
    if (!user.phone) return sendPhonePrompt(ctx, user.language);
    return sendAppScreen(ctx, user.language, { withConfirm: false });
  });

  bot.callbackQuery(/^lang:(om|am|en)$/, async (ctx) => {
    const lang = ctx.match[1];
    await User.updateOne({ telegramId: ctx.from.id }, { language: lang });
    await ctx.answerCallbackQuery();
    await sendPhonePrompt(ctx, lang);
  });

  bot.on('message:contact', async (ctx) => {
    const user = await User.findOne({ telegramId: ctx.from.id });
    if (!user?.language) return sendLanguageScreen(ctx);
    const lang = user.language;
    const contact = ctx.message.contact;

    // must be the sender's OWN number
    if (contact.user_id !== ctx.from.id) {
      await ctx.reply(tr(lang).notOwnPhone);
      return sendPhonePrompt(ctx, lang);
    }
    const phone = normalizePhone(contact.phone_number);
    if (config.onlyEthiopia && !phone.startsWith('+251')) {
      await ctx.reply(tr(lang).onlyEt);
      return sendPhonePrompt(ctx, lang);
    }
    user.phone = phone;
    await user.save();
    await sendAppScreen(ctx, lang, { withConfirm: true });
  });

  bot.catch((err) => console.error('Bot error:', err.message));
  return bot;
}

// Send a Telegram message to a user (silently ignores failures, e.g. user blocked the bot)
export async function sendTelegram(telegramId, text) {
  if (!bot) return;
  try {
    await bot.api.sendMessage(telegramId, text);
  } catch (e) {
    console.warn('Could not message', telegramId, e.message);
  }
}
import { User, BankAccount } from '../models/index.js';
// Tells every admin about a new order (receipt photo + details + button to open the admin panel)
export async function notifyAdminsNewOrder({ order, lottery, numbers, user }) {
  if (!bot || !config.adminIds.length) return;

  const bank = order.bankAccount ? await BankAccount.findById(order.bankAccount) : null;
  const who = user.username ? `@${user.username}` : `ID ${user.telegramId}`;
  const lines = [
    `🛒 New order #${order.code}`,
    `🚘 ${lottery.title} (${lottery.carName})`,
    `👤 ${order.fullName} · ${order.phone}`,
    `🆔 Telegram: ${who}`,
    `🎟 Numbers: ${numbers.map((n) => String(n).padStart(4, '0')).join(', ')}`,
    `💰 Total: ${order.total.toLocaleString('en-US')} Birr`,
  ];
  if (bank) lines.push(`🏦 Bank: ${bank.bankName}`);
  if (order.senderAccount) lines.push(`📤 Sent from: ${order.senderAccount}`);
  lines.push('', '⏳ Waiting for your approval.');
  const caption = lines.join('\n');

  const kb = new InlineKeyboard();
  if (config.webAppUrl.startsWith('https://')) kb.webApp('🛠 Open admin panel', `${config.webAppUrl}/admin`);
  const extra = kb.inline_keyboard.length ? { reply_markup: kb } : {};

  const file = path.join(config.uploadDir, order.receiptUrl.replace('/uploads/', ''));
  for (const adminId of new Set(config.adminIds)) {
    try {
      await bot.api.sendPhoto(adminId, new InputFile(file), { caption, ...extra });
    } catch {
      try {
        await bot.api.sendMessage(adminId, caption, extra); // if the photo could not be sent
      } catch (e) {
        console.warn('Could not notify admin', adminId, e.message);
      }
    }
  }
}